function EventTicket({event,onBuy}:{event:SellerEvent;onBuy:()=>void}){const remaining=Math.max(0,Number(event.ticket_quantity||0)-Number(event.tickets_sold||0));return <View style={s.eventCard}>{event.banner_url?<Image source={{uri:event.banner_url}} style={s.eventBanner}/>:<View style={[s.eventBanner,s.eventBannerFallback]}><I name="gift" size={34} color="#FFF" filled/></View>}<View style={s.eventTicketBody}><View style={s.eventTicketHeader}><Text style={s.eventName} numberOfLines={2}>{event.name}</Text><Text style={s.eventPrice}>{Number(event.ticket_price||0)>0?money(Number(event.ticket_price)):'Free'}</Text></View><Text style={s.eventDescription} numberOfLines={3}>{event.description||'Join this event from Girlies.'}</Text><View style={s.eventMeta}><Text style={s.muted}>{event.event_mode==='physical'?event.location||'Physical location':'Online in the app'}</Text><Text style={s.muted}>{new Date(event.starts_at).toLocaleString()}</Text></View><View style={s.ticketDivider}/><View style={s.ticketFooter}><Text style={s.muted}>{remaining} tickets left</Text><Pressable style={s.ticketButton} onPress={onBuy}><Text style={s.ticketButtonText}>{Number(event.ticket_price||0)>0?'Buy a ticket':'Get a ticket'}</Text></Pressable></View></View></View>}

function ShopViewsChart({data}:{data:SellerStudioSeriesPoint[]}){const points=data.slice(-7);const values=points.map(point=>Number(point.views||0));const max=Math.max(1,...values);const width=300;const height=145;return <View style={s.shopChart}><View style={[s.chartPlot,{width,height}]}>{[0,1,2,3].map(line=><View key={line} style={[s.chartGridLine,{top:12+line*34,width}]}/>)}{points.length?points.map((point,index)=>{const x=points.length===1?width/2:index/(points.length-1)*(width-16)+8;const y=12+(height-35)-(Number(point.views||0)/max)*(height-50);const next=points[index+1];let segment=null;if(next){const nx=(index+1)/(points.length-1)*(width-16)+8;const ny=12+(height-35)-(Number(next.views||0)/max)*(height-50);const dx=nx-x;const dy=ny-y;const length=Math.sqrt(dx*dx+dy*dy);segment=<View style={[s.chartSegment,{left:(x+nx)/2-length/2,top:(y+ny)/2,width:length,transform:[{rotate:(Math.atan2(dy,dx)*180/Math.PI)+'deg'}]}]}/>;}return <React.Fragment key={point.date}>{segment}<View style={[s.chartPoint,{left:x-5,top:y-5}]}/><Text style={[s.chartDate,{left:x-18,top:height-18}]}>{point.date.slice(5)}</Text></React.Fragment>}):<Text style={s.muted}>No activity in this period.</Text>}</View></View>}
